import javax.swing.*;
import java.awt.*;
import java.awt.geom.*;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.util.Base64;
import javax.imageio.ImageIO;

/**
 * LoadingScreen
 * -------------
 * Shown after character select, before the game world loads.
 * White walk-cycle sprite (28 frames) animates stationary in the bottom-left.
 */
public class LoadingScreen extends JPanel {

    // ── Sprite frame data (28 walkLeft frames, white silhouette, transparent bg) ──
    private static final String[] FRAME_DATA = {
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        ""
    };

    private final GameWindow window;

    private BufferedImage[] frames;
    private int currentFrame = 0;

    private static final int SPRITE_W = 93;
    private static final int SPRITE_H = 142;
    private static final int SPRITE_X = 24;

    private float    progress = 0f;
    private Runnable onLoadComplete;
    private boolean  callbackFired = false;

    private static final Color GOLD       = new Color(201, 150,  58);
    private static final Color GOLD_LIGHT = new Color(240, 192,  96);
    private static final Color GOLD_DARK  = new Color(100,  65,  15);

    private Timer spriteTimer;
    private Timer progressTimer;

    private boolean blinkOn  = true;
    private long    lastBlink = 0;

    public LoadingScreen(GameWindow window) {
        this.window = window;
        setBackground(Color.BLACK);
        setPreferredSize(new Dimension(GameWindow.WIDTH, GameWindow.HEIGHT));
        decodeFrames();
        buildTimers();
    }

    public void startLoading(Runnable onComplete) {
        this.onLoadComplete = onComplete;
        progress = 0f;
        currentFrame = 0;
        blinkOn = true;
        callbackFired = false;
        // Stop any previously running timers before restarting
        spriteTimer.stop();
        progressTimer.stop();
        spriteTimer.start();
        progressTimer.start();
    }

    public void stopLoading() {
        spriteTimer.stop();
        progressTimer.stop();
    }

    private void decodeFrames() {
        frames = new BufferedImage[FRAME_DATA.length];
        for (int i = 0; i < FRAME_DATA.length; i++) {
            try {
                byte[] bytes = Base64.getDecoder().decode(FRAME_DATA[i]);
                frames[i] = ImageIO.read(new ByteArrayInputStream(bytes));
            } catch (Exception e) {
                frames[i] = null;
            }
        }
    }

    private void buildTimers() {
        // ~16 fps sprite animation
        spriteTimer = new Timer(60, e -> {
            currentFrame = (currentFrame + 1) % frames.length;
            repaint();
        });
        spriteTimer.setInitialDelay(0);

        // Progress bar fills over ~4 s, then fires callback
        progressTimer = new Timer(80, e -> {
            if (progress < 100f) {
                progress += 0.6f + (float)(Math.random() * 1.2f);
                if (progress > 100f) progress = 100f;
                repaint();
            } else {
                progressTimer.stop();
                spriteTimer.stop();
                if (onLoadComplete != null && !callbackFired) {
                    callbackFired = true;
                    SwingUtilities.invokeLater(onLoadComplete);
                }
            }
        });
        progressTimer.setInitialDelay(200);
    }

    @Override
    protected void paintComponent(Graphics g) {
        super.paintComponent(g);
        Graphics2D g2 = (Graphics2D) g.create();
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING,      RenderingHints.VALUE_ANTIALIAS_ON);
        g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
        g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION,     RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);

        int W = getWidth(), H = getHeight();

        // Black background
        g2.setColor(Color.BLACK);
        g2.fillRect(0, 0, W, H);

        // Scanlines
        g2.setColor(new Color(255, 255, 255, 5));
        for (int sy = 0; sy < H; sy += 4) g2.drawLine(0, sy, W, sy);

        // Vignette
        RadialGradientPaint vig = new RadialGradientPaint(
            new Point2D.Float(W / 2f, H / 2f),
            Math.max(W, H) * 0.72f,
            new float[]{0.4f, 1.0f},
            new Color[]{new Color(0,0,0,0), new Color(0,0,0,190)});
        g2.setPaint(vig);
        g2.fillRect(0, 0, W, H);

        // Title
        drawTitle(g2, W, H);

        // Sprite fixed bottom-left
        int spriteY = H - SPRITE_H - 36;
        if (frames != null && frames[currentFrame] != null) {
            g2.setColor(new Color(255, 255, 255, 18));
            g2.fillOval(SPRITE_X - 6, H - 40, SPRITE_W + 12, 14);
            g2.drawImage(frames[currentFrame], SPRITE_X, spriteY, SPRITE_W, SPRITE_H, null);
        }

        // Progress bar (right of sprite)
        int barX = SPRITE_X + SPRITE_W + 18;
        int barY = H - 44;
        int barW = W - barX - 30;
        int barH = 3;

        g2.setColor(new Color(255, 255, 255, 28));
        g2.fillRect(barX, barY, barW, barH);

        int fillW = (int)(barW * progress / 100f);
        if (fillW > 0) {
            GradientPaint fill = new GradientPaint(
                barX, barY, new Color(200, 200, 200),
                barX + fillW, barY, Color.WHITE);
            g2.setPaint(fill);
            g2.fillRect(barX, barY, fillW, barH);
            g2.setColor(new Color(255, 255, 255, 180));
            g2.fillRect(barX + fillW - 4, barY - 1, 4, barH + 2);
        }

        // Blinking "LOADING XX%" text
        long now = System.currentTimeMillis();
        if (now - lastBlink > 550) { lastBlink = now; blinkOn = !blinkOn; }
        g2.setFont(new Font("Serif", Font.PLAIN, 11));
        g2.setColor(new Color(255, 255, 255, blinkOn ? 110 : 40));
        FontMetrics fm = g2.getFontMetrics();
        String pctStr = "LOADING   " + (int)progress + "%";
        g2.drawString(pctStr, barX + barW - fm.stringWidth(pctStr), barY - 8);

        g2.dispose();
    }

    private void drawTitle(Graphics2D g2, int W, int H) {
        Font topFont = new Font("Serif", Font.BOLD | Font.ITALIC, 48);
        g2.setFont(topFont);
        FontMetrics fm = g2.getFontMetrics();
        String topText = "GREAT RUINS OF";
        int topX = (W - fm.stringWidth(topText)) / 2;
        int topY = H / 2 - 90;

        g2.setColor(new Color(0, 0, 0, 160));
        g2.drawString(topText, topX + 2, topY + 2);
        GradientPaint gp1 = new GradientPaint(topX, topY - 48, GOLD_LIGHT, topX, topY, GOLD_DARK);
        g2.setPaint(gp1);
        g2.drawString(topText, topX, topY);

        Font bigFont = new Font("Serif", Font.BOLD, 140);
        g2.setFont(bigFont);
        fm = g2.getFontMetrics();
        String bigText = "KHAI";
        int bigX = (W - fm.stringWidth(bigText)) / 2;
        int bigY = H / 2 + 20;

        g2.setColor(new Color(60, 20, 0, 180));
        g2.drawString(bigText, bigX + 5, bigY + 5);
        g2.setColor(new Color(0, 0, 0, 120));
        g2.drawString(bigText, bigX + 2, bigY + 2);

        GradientPaint gp2 = new GradientPaint(bigX, bigY - 140, GOLD_LIGHT, bigX, bigY, GOLD_DARK);
        g2.setPaint(gp2);
        g2.drawString(bigText, bigX, bigY);

        int lineY = bigY + 18;
        g2.setColor(new Color(GOLD_DARK.getRed(), GOLD_DARK.getGreen(), GOLD_DARK.getBlue(), 120));
        g2.setStroke(new BasicStroke(1f));
        g2.drawLine((W - 300) / 2, lineY, (W + 300) / 2, lineY);
    }
}